const CACHE='stamattina-v2';const base=new URL('./',self.location).pathname;const shell=['','index.html','style.css','app.js','manifest.webmanifest','assets/icon.svg','assets/icon-192.png','assets/icon-512.png'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(shell.map(x=>base+x)))));self.addEventListener('activate',e=>e.waitUntil(Promise.all([caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('stamattina-')&&k!==CACHE).map(k=>caches.delete(k)))),self.clients.claim()])));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith((async()=>{const cache=await caches.open(CACHE);try{const r=await fetch(e.request);if(r.ok)await cache.put(e.request,r.clone());return r}catch{const old=await cache.match(e.request);if(old)return old;if(e.request.mode==='navigate')return await cache.match(base+'index.html');return new Response('Offline',{status:503})}})())});
